        {
            string output=null;try
            {
                var args=Environment.GetCommandLineArgs();int at=Array.IndexOf(args,"-earthUnscriptedDeeOutput");output=Path.GetFullPath(at>=0&&at+1<args.Length?args[at+1]:"Builds/Verification/DeeWidth/"+DateTime.UtcNow.ToString("yyyyMMdd-HHmmss-fffffff"));Directory.CreateDirectory(output);
                string sourcePath="Assets/EarthUnscripted/Resources/Geo/dee-valley.json";byte[] bytes=File.ReadAllBytes(sourcePath);string sourceSHA=Hash(bytes);File.WriteAllBytes(Path.Combine(output,"source-raw.json"),bytes);var source=JsonUtility.FromJson<GeoRegion>(Encoding.UTF8.GetString(bytes));int ordinary=source.roads.Length;bool prepareBase=!source.preparedWidths;
                if(prepareBase)foreach(var road in source.roads)road.width=source.circuit?road.width*1.35f:Mathf.Max(road.kind=="service"?6.5f:8.5f,road.width*1.4f);source.preparedWidths=true;source.Prepare();string ordinaryHash=RoadHash(source,ordinary);
